Definitions -->\n        <defs>\n          <marker id=\"arrowhead\" markerWidth=\"10\" markerHeight=\"7\" refX=\"9\" refY=\"3.5\" orient=\"auto\">\n            <polygon points=\"0 0, 10 3.5, 0 7\" class=\"m-default\" />\n          </marker>\n          <marker id=\"arrowhead-emphasis\" markerWidth=\"10\" markerHeight=\"7\" refX=\"9\" refY=\"3.5\" orient=\"auto\">\n            <polygon points=\"0 0, 10 3.5, 0 7\" class=\"m-emphasis\" />\n          </marker>\n          <marker id=\"arrowhead-security\" markerWidth=\"10\" markerHeight=\"7\" refX=\"9\" refY=\"3.5\" orient=\"auto\">\n            <polygon points=\"0 0, 10 3.5, 0 7\" class=\"m-security\" />\n          </marker>\n          <marker id=\"arrowhead-dashed\" markerWidth=\"10\" markerHeight=\"7\" refX=\"9\" refY=\"3.5\" orient=\"auto\">\n            <polygon points=\"0 0, 10 3.5, 0 7\" class=\"m-dashed\" />\n          </marker>\n          <pattern id=\"grid\" width=\"40\" height=\"40\" patternUnits=\"userSpaceOnUse\">\n            <path d=\"M 40 0 L 0 0 0 40\" class=\"c-grid\" stroke-width=\"0.5\"/>\n          </pattern>\n        </defs>\n\n        <!-- Background Grid -->\n        <rect width=\"100%\" height=\"100%\" fill=\"url(#grid)\" />\n\n        <!-- Boundaries (behind everything) -->\n\n\n        <!-- Connection paths (before components for correct z-order) -->\n        <path data-edge-from=\"rt-planner\" data-edge-to=\"rt-gate\" data-edge-label=\"带有效期目标\" data-edge-key=\"0\" data-edge-id=\"rt-command\" data-composition-points=\"270,173;410,173\" d=\"M 270 173 L 410 173\" class=\"a-emphasis\" stroke-width=\"1.8\" marker-end=\"url(#arrowhead-emphasis)\"/>\n        <path data-edge-from=\"rt-gate\" data-edge-to=\"rt-servo\" data-edge-label=\"有效目标\" data-edge-key=\"1\" data-edge-id=\"rt-accept\" data-composition-points=\"640,173;780,173\" d=\"M 640 173 L 780 173\" class=\"a-emphasis\" stroke-width=\"1.8\" marker-end=\"url(#arrowhead-emphasis)\"/>\n        <path data-edge-from=\"rt-servo\" data-edge-to=\"rt-dri